{"new_str": "  # --- xini --------------------------------------------------------------------
  if (is.null(xini)) {
    # Default: three points spread across the domain
    if (is.finite(lower) && is.finite(upper)) {
      width <- upper - lower
      xini <- c(lower + 0.1 * width,
                lower + 0.5 * width,
                upper - 0.1 * width)
    } else if (!is.finite(lower) && !is.finite(upper)) {
      # Both infinite: use symmetric points around 0
      xini <- c(-1, 0, 1)
    } else if (!is.finite(lower)) {
      # Lower is -Inf, upper is finite
      xini <- c(upper - 0.9 * abs(upper),
                upper - 0.5 * abs(upper),
                upper - 0.1 * abs(upper))
    } else {
      # Lower is finite, upper is +Inf
      xini <- c(lower + 0.1 * abs(lower),
                lower + 0.5 * abs(lower),
                lower + 0.9 * abs(lower))
    }
  } else {
    if (!is.numeric(xini) || length(xini) < 3)
      stop("ars: 'xini' must be a numeric vector with at least 3 elements.")
    xini <- sort(xini)
    # Check that all init points lie within the domain
    if (any(is.na(xini)) || any(!is.finite(xini)))
      stop("ars: all initial points in 'xini' must be finite and lie strictly inside (lower, upper).")
    if (any(xini <= lower) || any(xini >= upper))
      stop("ars: all initial points in 'xini' must lie strictly inside (lower, upper).")
  }
  xini <- unique(xini)
  if (length(xini) < 3)
    stop("ars: after removing duplicates, 'xini' must have at least 3 distinct points.")", "old_str": "  # --- xini --------------------------------------------------------------------
