{"new_str": "  m <- length(xi)
  if (m < 3) return(TRUE)

  secants <- diff(logy) / diff(xi)
  # Check monotone decreasing secant slopes
  if (!all(diff(secants) <= 1e-10)) {
    return(FALSE)
  }
  # Check each derivative lies between adjacent secants
  for (j in 2:(m-1)) {
    if (dlogy[j] > secants[j-1] + 1e-10 || dlogy[j] < secants[j] - 1e-10) {
      return(FALSE)
    }
  }
  # Endpoints: first derivative >= first secant, last derivative <= last secant
  if (dlogy[1] < secants[1] - 1e-10) return(FALSE)
  if (dlogy[m] > secants[m-1] + 1e-10) return(FALSE)", "old_str": "  m <- length(xi)
  if (m < 3) return(TRUE)

  secants <- (logy[-1] - logy[-m]) / (xi[-1] - xi[-(m-1)])
  # Check monotone decreasing secant slopes
  if (!all(diff(secants) <= 1e-10)) {
    return(FALSE)
  }
  # Check each derivative lies between adjacent secants
  for (j in 2:(m-1)) {
    if (dlogy[j] > secants[j-1] + 1e-10 || dlogy[j] < secants[j] - 1e-10) {
      return(FALSE)
    }
  }
  # Endpoints
  if (dlogy[1] < secants[1] - 1e-10) return(FALSE)
  if (dlogy[m] > secants[m-1] + 1e-10) return(FALSE)", "path": "/app/ars.R"}

